import pulp

# Define the problem
model = pulp.LpProblem("Vehicle_Allocation", pulp.LpMinimize)

# Sets
centers = ['C1', 'C2', 'C3', 'C4']
outlets = ['D1', 'D2', 'D3', 'D4']

# Supply (vehicles available at each distribution center)
supply = {'C1': 108, 'C2': 200, 'C3': 106, 'C4': 51}

# Demand (vehicles required at each retail outlet)
demand = {'D1': 70, 'D2': 26, 'D3': 100, 'D4': 94}

# Fuel cost per vehicle from center i to outlet j (cost matrix)
cost = {
    'C1': {'D1': 3, 'D2': 17, 'D3': 8, 'D4': 9},
    'C2': {'D1': 16, 'D2': 7, 'D3': 18, 'D4': 5},
    'C3': {'D1': 19, 'D2': 19, 'D3': 16, 'D4': 8},
    'C4': {'D1': 16, 'D2': 14, 'D3': 7, 'D4': 4}
}

# Decision variables: x[i][j] = number of vehicles sent from center i to outlet j
# These are integer variables (since we can't send fractional vehicles)
x = {}
for i in centers:
    for j in outlets:
        x[i][j] = pulp.LpVariable(f"x_{i}_{j}", lowBound=0, cat='Integer')

# Objective function: minimize total fuel cost
model += pulp.lpSum(cost[i][j] * x[i][j] for i in centers for j in outlets)

# Constraints: supply constraints (total vehicles sent from each center <= available)
for i in centers:
    model += pulp.lpSum(x[i][j] for j in outlets) <= supply[i], f"Supply_{i}"

# Constraints: demand constraints (total vehicles received at each outlet == required)
for j in outlets:
    model += pulp.lpSum(x[i][j] for i in centers) == demand[j], f"Demand_{j}"

# Solve the model using HiGHS solver
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output the solution (optional, for verification)
print("Optimal vehicle allocation:")
for i in centers:
    for j in outlets:
        if x[i][j].value() > 0:
            print(f"From {i} to {j}: {int(x[i][j].value())} vehicles")

print(f"Total minimum fuel cost: {int(pulp.value(model.objective))}")

