import pulp

# Define the problem
model = pulp.LpProblem("Traveling_Salesman_Problem", pulp.LpMinimize)

# Define the sites: 0 = Base, 1 = Site 1, 2 = Site 2, 3 = Site 3, 4 = Site 4, 5 = Site 5
sites = list(range(6))

# Travel times (in minutes) as given in the problem
# From Base (0) to sites
travel_times = {
    (0, 1): 104.7, (0, 2): 75.7, (0, 3): 83.9, (0, 4): 29.1, (0, 5): 87.7,
    (1, 2): 123.9, (1, 3): 136.7, (1, 4): 90.3, (1, 5): 75.6,
    (2, 3): 12.8, (2, 4): 99.2, (2, 5): 56.9,
    (3, 4): 109.0, (3, 5): 68.5,
    (4, 5): 96.2
}

# Add reverse edges (symmetric travel times)
for (i, j), time in list(travel_times.items()):
    travel_times[(j, i)] = time

# Add self-loops as 0 (not used, but for completeness)
for i in sites:
    travel_times[(i, i)] = 0

# Decision variables: x[i][j] = 1 if we travel from i to j, 0 otherwise
x = {}
for i in sites:
    for j in sites:
        if i != j:
            x[i, j] = pulp.LpVariable(f"x_{i}_{j}", cat='Binary')
        else:
            x[i, j] = 0  # No self-loops allowed

# Objective: minimize total travel time
model += pulp.lpSum([travel_times[i, j] * x[i, j] for i in sites for j in sites if i != j])

# Constraints: each site must be entered exactly once
for j in sites:
    model += pulp.lpSum([x[i, j] for i in sites if i != j]) == 1

# Constraints: each site must be left exactly once
for i in sites:
    model += pulp.lpSum([x[i, j] for j in sites if j != i]) == 1

# Subtour elimination: Miller-Tucker-Zemlin (MTZ) formulation
# We'll use u[i] as the order variable for site i (except base)
u = {}
for i in sites:
    if i == 0:  # Base
        u[i] = 0
    else:
        u[i] = pulp.LpVariable(f"u_{i}", lowBound=0, upBound=len(sites)-1, cat='Integer')

# For each pair (i, j) where i != j and i != 0 and j != 0, enforce: u[i] - u[j] + (n-1)*x[i,j] <= n-2
n = len(sites)
for i in sites:
    for j in sites:
        if i != j and i != 0 and j != 0:
            model += u[i] - u[j] + (n - 1) * x[i, j] <= n - 2

# The base (site 0) must be visited, and we must return to it
# This is handled by the in/out degree constraints above

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output the solution (optional, for verification)
if pulp.LpStatus[model.status] == "Optimal":
    print("Optimal route found:")
    current = 0  # Start at base
    route = [0]
    while True:
        next_site = None
        for j in sites:
            if j != current and x[current, j].value() > 0.5:
                next_site = j
                break
        if next_site is None:
            break
        route.append(next_site)
        current = next_site
        if current == 0:  # Back to base
            break
    print("Route:", route)
    print("Total travel time:", pulp.value(model.objective), "minutes")
else:
    print("No optimal solution found.")

